        `<div class="row"><span>deployAllowed</span><strong>${deployDecision?.deployAllowed ? 'yes' : 'no'}</strong></div>`,
        `<div class="row"><span>publicExposureAllowed</span><strong>${deployDecision?.publicExposureAllowed ? 'yes' : 'no'}</strong></div>`,
        '</section>',
      ].join('');
    })
    .join('');

