  const validLng =
    Number.isFinite(bbox.minLng) &&
    Number.isFinite(bbox.maxLng) &&
    bbox.minLng >= -180 &&
    bbox.maxLng <= 180 &&
    bbox.minLng < bbox.maxLng;

